INSERT INTO translations (locale, key, value) VALUES ('it', 'hero.title', 'Crooked House
INSERT INTO translations (locale, key, value) VALUES ('it', 'hero.description', 'Un soggiorno fuori dagli schemi, in una casa dal carattere unico, pensata per chi ama vivere qualcosa di davvero speciale.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('it', 'about.headline', 'Una casa caratteristica nel cuore del Lago di Como') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('it', 'about.p1', 'Un piccolo rifugio tra le montagne, a pochi passi dalle meraviglie del Lago di Como.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('it', 'about.p2', 'Nel cuore storico di **Naggio**, suggestiva frazione di Grandola ed Uniti, il tempo sembra scorrere più lentamente. Tra antiche case in pietra, silenzi di montagna e panorami incantevoli che si aprono sulle acque del **Lago di Como e del Lago di Lugano**, ogni momento invita a fermarsi, respirare e lasciarsi conquistare dalla bellezza del paesaggio.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('it', 'gallery.headline', 'Ogni angolo curato') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('it', 'gallery.body', '**Crooked House** è un intero appartamento con una camera da letto, restaurato con cura e arredato per offrire un soggiorno all''insegna del comfort, della bellezza e della semplicità.
INSERT INTO translations (locale, key, value) VALUES ('it', 'amenities.headline', 'Tutto il necessario per rilassarsi') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('it', 'amenities.body', '**Crooked House** dispone di tutto ciò che serve per rendere il soggiorno piacevole, confortevole e senza pensieri.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('it', 'amenities.list', '["Forno","Lavastoviglie","Microonde","Macchine da caffè per espresso, moka e caffè americano","Tostapane","Bollitore","TV a schermo piatto con accesso ai tuoi servizi di streaming preferiti","Wi-Fi gratuito in tutto l''appartamento","Armadio e cassettiera","Culla gratuita (120 × 60 cm), su richiesta","Biancheria da letto e da bagno inclusa","Asciugacapelli","Ferro da stiro","Giardino privato con tavolo e ombrellone","Locale lavanderia con lavatrice, asciugatrice e ampio lavatoio con acqua calda","Garage privato gratuito, adatto a un''auto di piccole o medie dimensioni"]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('it', 'explore.headline', 'Esplora il territorio') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('it', 'explore.body', '**Crooked House** è una base ideale per scoprire il Lago di Como e le sue montagne, combinando **relax, natura, sport e cultura.** La posizione permette di raggiungere facilmente località suggestive come **Menaggio, Tremezzina, Varenna e Bellagio,** oltre a numerosi itinerari per trekking, escursioni ed e-bike. È inoltre possibile estendere l''esperienza fino a **Lugano,** in Svizzera. Un soggiorno pensato per vivere il territorio tra borghi, ville storiche, paesaggi lacustri e panorami alpini.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('it', 'stay.headline', 'Scopri gli spazi') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('it', 'services.headline', 'Servizi e piccole attenzioni') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('it', 'services.body', 'Ogni soggiorno è pensato per offrirvi comfort, ospitalità e il calore di sentirvi a casa. Chi viaggia in moto può usufruire di un **parcheggio dedicato direttamente in struttura.**
