INSERT INTO translations (locale, key, value) VALUES ('en', 'hero.title', 'Crooked House
INSERT INTO translations (locale, key, value) VALUES ('en', 'hero.description', 'A stay beyond the ordinary, in a house with a unique character, designed for those who love to experience something truly special.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('en', 'about.headline', 'A characterful village home for slow, sunlit days') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('en', 'about.p1', 'Set in the quiet village of Grandola ed Uniti, just above Menaggio on Lake Como, Crooked House is a lovingly restored one-bedroom apartment. White plaster walls, exposed wooden beams, and cool tiled floors keep the atmosphere calm and airy even on the warmest afternoons.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('en', 'about.p2', 'You''ll have the whole apartment to yourself  a **private entrance**, a **comfortable living room**, a **fully equipped kitchen**, and a **garden framed by the mountains**.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('en', 'gallery.headline', 'Every corner, thoughtfully considered') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('en', 'gallery.body', 'From the cosy bedroom to the mountain-framed garden, take a look around before you arrive.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('en', 'amenities.headline', 'Everything you need to unwind') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('en', 'amenities.body', '**Crooked House** has everything you need for a pleasant, comfortable, and worry-free stay.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('en', 'amenities.list', '["Oven","Dishwasher","Microwave","Coffee machines for espresso, moka, and American-style coffee","Toaster","Kettle","Flat-screen TV with access to your favourite streaming services","Free Wi-Fi throughout the apartment","Wardrobe and chest of drawers","Free cot (120 × 60 cm), available on request","Bed linen and towels included","Hairdryer","Iron and ironing board","Private garden with table and parasol","Laundry room with washing machine, dryer, and large sink with hot water","Free private garage, suitable for a small or medium-sized car"]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('en', 'explore.headline', 'Explore the area') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('en', 'explore.body', '**Crooked House** is the ideal base for discovering Lake Como and its mountains, blending **relaxation, nature, sport, and culture.** Its location makes it easy to reach enchanting towns such as **Menaggio, Tremezzina, Varenna, and Bellagio,** as well as countless trekking, hiking, and e-bike routes. You can even extend your experience across the border to **Lugano,** in Switzerland. A stay designed for enjoying the territory through its villages, historic villas, lakeside landscapes, and alpine views.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('en', 'stay.headline', 'Discover the spaces') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('en', 'services.headline', 'Services and thoughtful touches') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('en', 'services.body', 'Every stay is designed to offer you comfort, hospitality, and the warmth of feeling at home. If you''re travelling by motorbike, you can use a **dedicated parking space right at the property.**
