INSERT INTO translations (locale, key, value) VALUES ('fr', 'hero.description', 'Crooked House est un appartement de charme avec une chambre à coucher au-dessus de Menaggio, une entrée privée, un jardin encadré par les montagnes et une cuisine entièrement à vous.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('fr', 'about.headline', 'Une maison de village pleine de caractère pour des journées lentes et ensoleillées') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('fr', 'about.p1', 'Nichée dans le paisible village de Grandola ed Uniti, juste au-dessus de Menaggio sur le lac de Côme, Crooked House est un appartement avec une chambre à coucher restauré avec soin. Les murs blancs en plâtre, les poutres apparentes et les sols carrelés frais gardent une ambiance calme et aérienne même les après-midi les plus chauds.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('fr', 'about.p2', 'Vous aurez tout l''appartement pour vous une **entrée privée**, un **salon confortable**, une **cuisine entièrement équipée** et un **jardin encadré par les montagnes**.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('fr', 'gallery.headline', 'Chaque recoin pensé avec soin') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('fr', 'gallery.body', 'De la chambre cosy au jardin entouré de montagnes, découvrez les lieux avant votre arrivée.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('fr', 'amenities.headline', 'Tout ce qu''il faut pour se détendre') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('fr', 'amenities.body', '**Crooked House** dispose de tout ce qu''il faut pour rendre le séjour agréable, confortable et sans souci.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('fr', 'amenities.list', '["Four","Lave-vaisselle","Micro-ondes","Machines à café pour espresso, moka et café américain","Grille-pain","Bouilloire","TV écran plat avec accès à vos services de streaming préférés","Wi-Fi gratuit dans tout l''appartement","Armoire et commode","Berceau gratuit (120 × 60 cm), sur demande","Linge de lit et de salle de bain inclus","Sèche-cheveux","Fer à repasser","Jardin privé avec table et parasol","Buanderie avec machine à laver, sèche-linge et grand évier avec eau chaude","Garage privé gratuit, adapté à une voiture petite ou moyenne"]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('fr', 'explore.headline', 'Découvrez le territoire') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('fr', 'explore.body', '**Crooked House** est la base idéale pour découvrir le lac de Côme et ses montagnes, combinant **détente, nature, sport et culture.** Sa position permet d''atteindre facilement des villages pittoresques comme **Menaggio, Tremezzina, Varenna et Bellagio,** ainsi que de nombreux itinéraires de randonnée et VTT électrique. Il est également possible d''étendre l''expérience jusqu''à **Lugano,** en Suisse. Un séjour pensé pour vivre le territoire entre villages, villas historiques, paysages lacustres et panoramas alpins.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('fr', 'stay.headline', 'Tout l''espace est à vous') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
