INSERT INTO translations (locale, key, value) VALUES ('fr', 'services.body', 'Chaque séjour est pensé pour vous offrir confort, hospitalité et la chaleur de se sentir chez soi. Les voyageurs en moto peuvent bénéficier d''un **parking dédié directement sur place.**
