INSERT INTO translations (locale, key, value) VALUES ('de', 'hero.badge', '{score} · {count} Bewertungen · Grandola ed Uniti, Comer See') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'hero.title', 'Dein eigenes Eck am Comer See') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'hero.description', 'Crooked House ist eine charmante Ferienwohnung mit einem Schlafzimmer über Menaggio, mit eigenem Eingang, einem von Bergen umrahmten Garten und einer Küche, die ganz dir gehört.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'about.headline', 'Ein charaktervolles Dorfhaus für ruhige, sonnige Tage') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'about.p1', 'Eingebettet im ruhigen Dorf Grandola ed Uniti, direkt oberhalb von Menaggio am Comer See, ist Crooked House eine liebevoll restaurierte Wohnung mit einem Schlafzimmer. Weiße Putzwände, sichtbare Holzbohlen und kühle Fliesen schaffen eine ruhige, luftige Atmosphäre, auch an den wärmsten Nachmittagen.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'about.p2', 'Du hast die gesamte Wohnung für dich allein mit **eigenem Eingang**, einem **gemütlichen Wohnzimmer**, einer **voll ausgestatteten Küche** und einem **von Bergen umrahmten Garten**.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'gallery.headline', 'Jede Ecke mit viel Liebe gestaltet') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'gallery.body', 'Von der gemütlichen Schlafkammer bis zum von Bergen umrahmten Garten mach dich vor deiner Ankunft mit dem Ort vertraut.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'amenities.headline', 'Alles, was du zum Entspannen brauchst') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'amenities.body', '**Crooked House** bietet alles, was du für einen angenehmen, komfortablen und sorgenfreien Aufenthalt brauchst.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'amenities.list', '["Backofen","Geschirrspüler","Mikrowelle","Kaffeeautomaten für Espresso, Moka und amerikanischen Kaffee","Toaster","Wasserkocher","Flachbildfernseher mit Zugang zu deinen Lieblings-Streamingdiensten","Kostenloses WLAN in der gesamten Wohnung","Kleiderschrank und Kommode","Kostenloses Babybett (120 × 60 cm), auf Anfrage","Bettwäsche und Handtücher inklusive","Föhn","Bügeleisen","Privater Garten mit Tisch und Sonnenschirm","Waschküche mit Waschmaschine, Trockner und großem Waschbecken mit Warmwasser","Kostenloser privater Garage, geeignet für ein kleines oder mittleres Auto"]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'explore.headline', 'Entdecke die Umgebung') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'explore.body', '**Crooked House** ist der ideale Ausgangspunkt, um den Comer See und seine Berge zu entdecken und dabei **Entspannung, Natur, Sport und Kultur** zu verbinden. Die Lage macht es einfach, malerische Orte wie **Menaggio, Tremezzina, Varenna und Bellagio** zu erreichen, ebenso wie zahlreiche Wander- und E-Bike-Strecken. Du kannst dein Erlebnis sogar bis nach **Lugano** in der Schweiz ausweiten. Ein Aufenthalt, der darauf ausgelegt ist, das Territorium zwischen Dörfern, historischen Villen, See Landschaften und Alpenpanoramen zu genießen.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'stay.headline', 'Der ganze Ort ist dein') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'services.headline', 'Services und kleine Aufmerksamkeiten') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('de', 'services.body', 'Jeder Aufenthalt ist darauf ausgelegt, dir Komfort, Gastfreundschaft und die Wärme zu bieten, sich wie zu Hause zu fühlen. Motorradfahrer können einen **dedizierten Parkplatz direkt in der Unterkunft** nutzen.
INSERT INTO translations (locale, key, value) VALUES ('de', 'reviews.headline', 'Von jedem Gast als außergewöhnlich bewertet') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
