INSERT INTO translations (locale, key, value) VALUES ('es', 'hero.badge', '{score} · {count} reseñas · Grandola ed Uniti, Lago de Como') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'hero.title', 'Tu rincón del Lago de Como') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'hero.description', 'Crooked House es un apartamento con encanto de una habitación situado sobre Menaggio, con entrada privada, jardín rodeado de montañas y una cocina que es toda tuya.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'about.headline', 'Una casa de pueblo con carácter para días lentos y soleados') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'about.p1', 'Oculto en el tranquilo pueblo de Grandola ed Uniti, justo encima de Menaggio en el Lago de Como, Crooked House es un apartamento de una habitación restaurado con mimo. Las paredes de yeso blanco, las vigas de madera vistas y los suelos de baldosas mantienen un ambiente sereno y aireado incluso en las tardes más cálidas.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'about.p2', 'Tendrás todo el apartamento para ti: **entrada privada**, **salón cómodo**, **cocina totalmente equipada** y un **jardín enmarcado por las montañas**.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'gallery.headline', 'Cada rincón pensado con detalle') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'gallery.body', 'Desde el dormitorio acogedor hasta el jardín rodeado de montañas, descubre el lugar antes de llegar.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'amenities.headline', 'Todo lo necesario para relajarse') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'amenities.body', '**Crooked House** dispone de todo lo necesario para que el alojamiento sea agradable, cómodo y sin preocupaciones.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'amenities.list', '["Horno","Lavavajillas","Microondas","Máquinas de café para espresso, moka y café americano","Tostadora","Hervidor","Televisor de pantalla plana con acceso a tus servicios de streaming favoritos","Wi-Fi gratuito en todo el apartamento","Armario y cómoda","Cuna gratuita (120 × 60 cm), bajo solicitud","Ropa de cama y toallas incluidas","Secador de pelo","Plancha","Jardín privado con mesa y sombrilla","Local de lavandería con lavadora, secadora y amplio fregadero con agua caliente","Garaje privado gratuito, adecuado para un coche pequeño o mediano"]') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'explore.headline', 'Explora el territorio') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'explore.body', 'Crooked House es la base ideal para descubrir el Lago de Como y sus montañas, combinando relax, naturaleza, deporte y cultura. Su ubicación permite llegar fácilmente a localidades pintorescas como Menaggio, Tremezzina, Varenna y Bellagio, además de numerosos itinerarios de senderismo, excursiones y bicicleta eléctrica. También es posible extender la experiencia hasta Lugano, en Suiza. Un alojamiento pensado para vivir el territorio entre pueblos, villas históricas, paisajes lacustres y panoramas alpinos.') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'stay.headline', 'Descubre los espacios') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'services.headline', 'Servicios y pequeñas atenciones') ON CONFLICT(locale, key) DO UPDATE SET value = excluded.value;
INSERT INTO translations (locale, key, value) VALUES ('es', 'services.body', 'Cada estancia está pensada para ofreceros comodidad, hospitalidad y el calor de sentirse en casa. Los que viajan en moto pueden disfrutar de un **parking dedicado directamente en la estructura.**
